namespace Asset.Domain.Entities;

// One plug-in of a USB storage device on a PC, from mount to unplug. The Id is generated by the agent so
// re-sent batches stay idempotent. DeviceId is null when MachineName matches no Device (asset-module.md §1.24).
public partial class UsbSession
{
    public Guid Id { get; set; }

    public string MachineName { get; set; } = null!;

    public int? DeviceId { get; set; }

    public int UsbDeviceId { get; set; }

    public string? WindowsUser { get; set; }

    public string? DriveLetter { get; set; }

    public string? VolumeLabel { get; set; }

    public DateTime ConnectedAt { get; set; }

    public DateTime? DisconnectedAt { get; set; }

    // False when the PC had Device.IsUseUsb = false at plug-in (the flag is then switched on, so this column is
    // the only record of the unpermitted use); null when MachineName matches no Device.
    public bool? WasPermitted { get; set; }

    public virtual Device? Device { get; set; }

    public virtual UsbDevice UsbDevice { get; set; } = null!;

    public virtual ICollection<UsbFileEvent> FileEvents { get; set; } = new List<UsbFileEvent>();
}
